$assertions=0;$tests=0;$fixtureUsers=[];
function check($condition,$description){global $assertions;$assertions++;if(!$condition)throw new RuntimeException($description);}
function test($name,$work){global $tests;try{$work();$tests++;echo "PASS $name\n";}catch(Throwable $e){echo "FAIL $name: ".$e->getMessage()."\n";throw $e;}}
function rejects($work,$key){try{$work();}catch(Fault $e){check($e->key===$key,"Expected $key, got {$e->key}");return;}throw new RuntimeException("Expected $key");}
function session_fixture($char='a'){$_COOKIE[Session::COOKIE]=str_repeat($char,64);$hash=Session::hash();if(!Session::current())Db::insert('sessions',['hash'=>$hash,'user_id'=>0,'expires_at'=>gmdate('Y-m-d H:i:s',time()+3600),'created_at'=>Db::now()]);}
function payload($amount=25000){return ['amount'=>$amount,'name'=>'Pendukung Uji','email'=>'donation-fixture@example.invalid','message'=>'<b>Semangat</b>','public_name'=>true,'public_message'=>false,'idempotency_key'=>bin2hex(random_bytes(16))];}
function gateway_payload($a,$state='settlement',$refund=0){return ['order_id'=>$a['order_id'],'gross_amount'=>$a['amount'].'.00','transaction_id'=>($a['transaction_id']??'')?:'fixture-transaction-'.$a['id'],'transaction_status'=>$state,'payment_type'=>'qris','merchant_id'=>$a['merchant'],'currency'=>'IDR','settlement_time'=>'2026-10-31 12:00:00','transaction_time'=>'2026-10-31 11:00:00','refund_amount'=>$refund.'.00','status_code'=>'200'];}
function parallel_workers($action,$extra=[]){$workers=[];for($i=0;$i<4;$i++){$pipes=[];$process=proc_open(array_merge([PHP_BINARY,'-c',php_ini_loaded_file(),__DIR__.'/worker.php',$action],$extra),[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$workers[]=[$process,$pipes];}$results=[];foreach($workers as [$process,$pipes]){$output=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($process);if($code!==0)throw new RuntimeException('Concurrent worker failed: '.$error);$results[]=json_decode($output,true,512,JSON_THROW_ON_ERROR);}return $results;}
