 test('CIDR, spoofed proxy, IPv6 chains, authenticated encryption',function(){check(Ip::resolve('203.0.113.5','1.1.1.1',['10.0.0.0/8'])==='203.0.113.5','untrusted ignored');check(Ip::resolve('10.0.0.1','198.51.100.3, 10.1.2.3',['10.0.0.0/8'])==='198.51.100.3','trusted chain');check(Ip::contains('2001:db8::1','2001:db8::/32'),'ipv6');check(!Ip::contains('2001:db9::1','2001:db8::/32'),'ipv6 boundary');check(Ip::contains('127.0.0.1','0.0.0.0/0'),'zero network');check(!Ip::valid_cidr('127.0.0.1/33'),'invalid CIDR');$blob=Crypto::seal('2001:db8::1',true);check(Crypto::open($blob,true)==='2001:db8::1','decrypt');check(Crypto::open('missing:'.explode(':',$blob,2)[1],true)===null,'missing key');$decoded=base64_decode(explode(':',$blob,2)[1]);$decoded[30]=chr(ord($decoded[30])^1);check(Crypto::open('fixture-v1:'.base64_encode($decoded),true)===null,'tamper rejected');});
