 test('member claim needs mailbox proof; all nonadmin roles denied',function()use(&$fixtureUsers){require_once ABSPATH.'wp-admin/includes/user.php';$guest=Db::tx(fn()=>Identity::donor('claim@example.invalid','Guest Claim'));$intent=['reference'=>bin2hex(random_bytes(16)),'donor_id'=>$guest['id'],'scope_hash'=>hash('sha256','claim'),'idempotency_hash'=>hash('sha256','claim'),'payload_hash'=>hash('sha256','claim'),'amount'=>10000,'alias'=>'Private alias','message'=>'','public_name'=>0,'public_message'=>0,'created_at'=>Db::now()];$intent['id']=Db::insert('intents',$intent);$code=bin2hex(random_bytes(32));Db::insert('tokens',['hash'=>hash('sha256',$code),'donor_id'=>$guest['id'],'purpose'=>'verify','expires_at'=>gmdate('Y-m-d H:i:s',time()+600),'created_at'=>Db::now()]);foreach(['mgd_member','mgd_mentor','mgd_moderator','administrator']as $role){$id=wp_insert_user(['user_login'=>'mgdd_it_'.bin2hex(random_bytes(5)),'user_pass'=>wp_generate_password(32),'user_email'=>'mgdd-'.bin2hex(random_bytes(5)).'@example.invalid','role'=>$role]);check(!is_wp_error($id),'fixture user');$fixtureUsers[]=$id;wp_set_current_user($id);$nonce=wp_create_nonce('wp_rest');foreach(rest_get_server()->get_routes()as $path=>$routes){if(!str_starts_with($path,'/'.Rest::NS.'/admin/'))continue;foreach($routes as $route){if(!isset($route['permission_callback']))continue;$r=new WP_REST_Request('POST',$path);$r->set_header('X-WP-Nonce',$nonce);$allowed=$route['permission_callback']($r);check($role==='administrator'?!is_wp_error($allowed):is_wp_error($allowed),'capability '.$role.' '.$path);}}if($role==='mgd_member'){$claimed=Identity::consume($code,true);check(in_array($intent['reference'],$claimed['references'],true),'claim history');$i=Donations::intent($intent['reference']);check(!$i['public_name'],'claim preserves private consent');$export=apply_filters('magaudev_export_user_data',[],$id);check(count($export['donations'])===1,'only explicitly claimed member history');}}wp_set_current_user(0);});
